package cn.cccs7.cynexus.market.application.controller;
import cn.cccs7.cynexus.common.core.result.Result; import cn.cccs7.cynexus.market.api.dto.MarketFactorSetDTO; import cn.cccs7.cynexus.market.application.service.MarketFactorSetAppService; import cn.cccs7.cynexus.market.application.service.stockselection.StockSelectionIdentityResolver; import cn.cccs7.cynexus.market.domain.factorresearch.MarketFactorSetBO; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/market/screener/factor-research/factor-sets") public class MarketFactorSetController {
 private final MarketFactorSetAppService app; private final StockSelectionIdentityResolver identity;
 public MarketFactorSetController(MarketFactorSetAppService app,StockSelectionIdentityResolver identity){this.app=app;this.identity=identity;}
 @GetMapping public Result<MarketFactorSetDTO.ListResponse> list(@RequestHeader(value="X-Cynexus-Principal",required=false) String p,@RequestHeader(value="X-Cynexus-Tenant",required=false) String t,@RequestHeader(value="X-Cynexus-Identity-Signature",required=false) String sig,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="50") int limit){return Result.success(app.list(scope(p,t,sig),offset,limit));}
 @GetMapping("/{code}") public Result<MarketFactorSetDTO.Response> get(@PathVariable String code,@RequestHeader(value="X-Cynexus-Principal",required=false) String p,@RequestHeader(value="X-Cynexus-Tenant",required=false) String t,@RequestHeader(value="X-Cynexus-Identity-Signature",required=false) String sig){return Result.success(app.get(scope(p,t,sig),code));}
 @PostMapping public Result<MarketFactorSetDTO.Response> create(@RequestBody MarketFactorSetDTO.CreateRequest r,@RequestHeader(value="X-Cynexus-Principal",required=false) String p,@RequestHeader(value="X-Cynexus-Tenant",required=false) String t,@RequestHeader(value="X-Cynexus-Identity-Signature",required=false) String sig){return Result.success(app.create(scope(p,t,sig),r));}
 @PutMapping("/{code}") public Result<MarketFactorSetDTO.Response> update(@PathVariable String code,@RequestBody MarketFactorSetDTO.UpdateRequest r,@RequestHeader(value="X-Cynexus-Principal",required=false) String p,@RequestHeader(value="X-Cynexus-Tenant",required=false) String t,@RequestHeader(value="X-Cynexus-Identity-Signature",required=false) String sig){return Result.success(app.update(scope(p,t,sig),code,r));}
 @PostMapping("/{code}/versions/validate") public Result<MarketFactorSetDTO.Version> validate(@PathVariable String code,@RequestBody MarketFactorSetDTO.ValidateRequest r,@RequestHeader(value="X-Cynexus-Principal",required=false) String p,@RequestHeader(value="X-Cynexus-Tenant",required=false) String t,@RequestHeader(value="X-Cynexus-Identity-Signature",required=false) String sig){return Result.success(app.validate(scope(p,t,sig),code,r));}
 @PostMapping("/{code}/versions/{versionNo}/promote") public Result<MarketFactorSetDTO.Version> promote(@PathVariable String code,@PathVariable int versionNo,@RequestHeader(value="X-Cynexus-Principal",required=false) String p,@RequestHeader(value="X-Cynexus-Tenant",required=false) String t,@RequestHeader(value="X-Cynexus-Identity-Signature",required=false) String sig){return Result.success(app.promote(scope(p,t,sig),code,versionNo));}
 @PostMapping("/{code}/versions/{versionNo}/screen-preview") public Result<MarketFactorSetDTO.PreviewResponse> preview(@PathVariable String code,@PathVariable int versionNo,@RequestBody(required=false) MarketFactorSetDTO.PreviewRequest r,@RequestHeader(value="X-Cynexus-Principal",required=false) String p,@RequestHeader(value="X-Cynexus-Tenant",required=false) String t,@RequestHeader(value="X-Cynexus-Identity-Signature",required=false) String sig){return Result.success(app.preview(scope(p,t,sig),code,versionNo,r));}
 @GetMapping("/{code}/versions/{versionNo}/strategy-handoff") public Result<MarketFactorSetDTO.StrategyHandoffResponse> strategyHandoff(@PathVariable String code,@PathVariable int versionNo,@RequestHeader(value="X-Cynexus-Principal",required=false) String p,@RequestHeader(value="X-Cynexus-Tenant",required=false) String t,@RequestHeader(value="X-Cynexus-Identity-Signature",required=false) String sig){return Result.success(app.strategyHandoff(scope(p,t,sig),code,versionNo));}
 private MarketFactorSetBO.Scope scope(String p,String t,String s){var v=identity.resolve(p,t,s);return new MarketFactorSetBO.Scope(v.tenantId(),v.ownerId());}
}
